CREATE TABLE projects (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id), name TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', template TEXT NOT NULL DEFAULT 'blank', viewer TEXT NOT NULL DEFAULT 'gallery', status TEXT NOT NULL DEFAULT 'active', phases TEXT NOT NULL DEFAULT '[]', fields TEXT NOT NULL DEFAULT '[]', options TEXT NOT NULL DEFAULT '{}', team TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX projects_client ON projects(client_id);
CREATE TABLE project_tasks (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), phase_id TEXT NOT NULL DEFAULT '', column_key TEXT NOT NULL DEFAULT 'todo', position INTEGER NOT NULL DEFAULT 0, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', assignee TEXT NOT NULL DEFAULT '', due TEXT NOT NULL DEFAULT '', visible INTEGER NOT NULL DEFAULT 0, client_task INTEGER NOT NULL DEFAULT 0, deliverable INTEGER NOT NULL DEFAULT 0, views TEXT NOT NULL DEFAULT '[]', checklist TEXT NOT NULL DEFAULT '[]', links TEXT NOT NULL DEFAULT '', done_at TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX project_tasks_project ON project_tasks(project_id);
CREATE TABLE project_comments (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES project_tasks(id), author TEXT NOT NULL, role TEXT NOT NULL, body TEXT NOT NULL, internal INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX project_comments_task ON project_comments(task_id);
CREATE TABLE project_reviews (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES project_tasks(id), actor TEXT NOT NULL, email TEXT NOT NULL, role TEXT NOT NULL, decision TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX project_reviews_task ON project_reviews(task_id);
